# -*- coding: utf-8 -*-
"""Rhythm strips and rhythm vignettes, pool C -- BLOCKS, VENTRICULAR and ARREST rhythms described
in words (CMS I Exam 5, Lecture 30 deck).

Each stem is a patient whose rhythm is DESCRIBED (rate, regularity, P waves and their relation to
the QRS, PR interval, QRS width and shape). Lead-ins spread over the rhythm, its cause, the
describing features, the test, the next step and the treatment.

KEYS ARE WRITTEN SHORT ON PURPOSE -- detail lives in the explanation. Slides only; the caps and
contested-slide decisions in cms_e5l30_scope.py hold here too (atropine and epinephrine are never
keyed for Mobitz type II or complete block; no shock counts; no QT drug list).
"""
import os, sys
sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from _cmse3_q import Q
from cms_e5rhy_scope import *


def V(topic, io, q, opts, cite, slot, lead):
    d = Q(topic, io, q, opts, cite)
    d["slot"] = slot
    d["lead"] = lead
    return d


PRE = "Premature beats"
AVB = "First- and second-degree block"
CHB = "Third-degree block"
BBB = "Bundle branch blocks"
VTA = "Ventricular tachycardia"
TDP = "Torsades de pointes"
ARR = "Cardiac arrest rhythms"

